@icontract.snapshot(lambda points: points[:], name="original_points")
@icontract.ensure(lambda result, k, original_points: len(result) == min(k, len(original_points)))
@icontract.ensure(lambda result, original_points: all(p in original_points for p in result))
@icontract.ensure(lambda result, original_points, origin: 
    len(result) == 0 or len(original_points) == len(result) or
    all(
        distance(p_in, origin) <= distance(p_out, origin)
        for p_in in result
        for p_out in original_points 
        if p_out not in result
    )
)

@icontract.snapshot(lambda points: [tuple(p) for p in points], name="original_points")
@icontract.ensure(lambda result, k, points: len(result) == min(k, len(points)))
@icontract.ensure(lambda result, OLD: all(tuple(p) in OLD.original_points for p in result))
@icontract.ensure(lambda result, OLD, k, origin: 
    len(result) == 0 or 
    len(OLD.original_points) <= k or
    all(
        distance(excluded_point, origin) >= max(distance(included_point, origin) for included_point in result)
        for excluded_point in OLD.original_points 
        if tuple(excluded_point) not in [tuple(p) for p in result]
    )
)

@icontract.ensure(lambda result, k, points: len(result) == min(k, len(points)))
@icontract.ensure(lambda result, points: all(p in points for p in result))
@icontract.ensure(lambda result, points, k, origin: 
    len(result) == 0 or 
    all(distance(p, origin) >= max(distance(r, origin) for r in result) 
        for p in points if p not in result))

@icontract.snapshot(lambda points: [tuple(p) for p in points], name="original_points")
@icontract.snapshot(lambda points: len(points), name="original_len")
@icontract.ensure(lambda result, k, original_len: len(result) == min(k, original_len))
@icontract.ensure(lambda result, original_points: all(tuple(p) in original_points for p in result))
@icontract.ensure(
    lambda result, original_points, origin: 
    len(result) >= len(original_points) or
    all(
        distance(p_in, origin) <= distance(p_out, origin) 
        for p_in in result 
        for p_out in [p for p in original_points if p not in [tuple(r) for r in result]]
    )
)

@icontract.snapshot(lambda points, origin: sorted([distance(p, origin) for p in points]), name="all_distances")
@icontract.ensure(lambda result, k, points: len(result) == min(k, len(points)))
@icontract.ensure(lambda result, points: all(p in points for p in result))
@icontract.ensure(lambda result, points, origin, all_distances, k: len(result) == 0 or all(distance(p, origin) <= all_distances[min(k, len(points))-1] if min(k, len(points)) <= len(all_distances) else float('inf') for p in result))
@icontract.ensure(lambda result, points, origin, all_distances, k: len(result) >= len(points) or all(distance(p, origin) >= all_distances[min(k, len(points))-1] if min(k, len(points)) > 0 else 0 for p in points if p not in result))
